{
  "name": "@amykit/plugin-file-worktree",
  "version": "0.6.0",
  "description": "One isolated checkout per piece of work, created or reused, pruned by retention.",
  "type": "module",
  "license": "MIT",
  "author": "Nicolas Melo",
  "homepage": "https://github.com/nicolasmelo1/amy#readme",
  "bugs": "https://github.com/nicolasmelo1/amy/issues",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nicolasmelo1/amy.git",
    "directory": "plugins/file-worktree"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "dependencies": {
    "@amykit/core": "^0.6.0",
    "zod": "^4.6.7"
  }
}

import { BRANCH_SETTINGS, ConfigSchema } from "@amykit/core";

/**
 * What this plugin needs told to it, and nothing more.
 *
 * The workspace is this plugin's: the repositories the machine's work happens
 * in, where their standing checkouts live, the branches new work is cut from
 * and the worktrees themselves all moved here out of the machine's top level,
 * so an install that drives no code carries none of it.
 */
export const configSchema = {
  repos: {
    type: "string[]",
    description: "the repositories this workspace's work happens in, from review load to where an errand may be done",
    default: [],
  },
  workspaceRoot: {
    type: "string",
    description: "where one checkout per repository lives; `~` is expanded. The default is where this command was typed",
    default: ".",
  },
  root: {
    type: "string",
    description:
      "where the worktrees live, outside every repository. `~` is expanded. The default is beside the state directory, which keeps one install's trees together",
    default: "",
  },
  workflow: {
    type: "string",
    description:
      "the first path segment of every tree this mount creates, so two workflows under one install never share a tree",
    default: "",
  },
  recordsDirectory: {
    type: "string",
    description:
      "where this profile stores workflow records. The host derives it so phase-local worktrees consult the same records as the mounted file store",
    default: "",
  },
  ...BRANCH_SETTINGS,
  checkouts: {
    type: "record",
    description:
      "where one repository's standing checkout is, instead of under the workspace root. A repository named here is never looked for under `root` at all",
    default: {},
  },
  retentionDays: {
    type: "number",
    description:
      "how many days a terminal, clean tree stays before a prune may remove it. A dirty, failed or in-flight tree is never a prune's",
    default: 7,
  },
} satisfies ConfigSchema;

export { plugin } from "./plugin.js";
export { configSchema } from "./config.js";
export { WorktreeManager } from "./manager.js";
export type { WorktreeManagerConfig } from "./manager.js";

import fs from "node:fs";
import path from "node:path";
import { baseBranchFor, CommandRunner, EventLog, Worktree, WorktreeInfo } from "@amykit/core";

export interface WorktreeManagerConfig {
  /** Where every tree lives, outside any repository. `~` is expanded. */
  root: string;
  /** The workflow this install drives, which is the first path segment. */
  workflow: string;
  /** The branch new trees are cut from, for a repository that named none. */
  defaultBranch: string;
  /**
   * Where one repository's base branch is, instead of the fallback.
   *
   * The cut a tree is made from is the same answer `Git` cuts a work
   * branch from, so the two cannot disagree about what a repository's
   * base is: one map, one resolution, handed to both.
   */
  baseBranch?: Readonly<Record<string, string>>;
  /** The standing checkouts, used only as the source for a named repository. */
  workspaceRoot?: string;
  /**
   * Where one repository's standing checkout is, instead of under the root.
   *
   * The source a tree is cut from is the same answer `Git` resolves, so a
   * repository named here is never looked for under `workspaceRoot` at all.
   */
  checkouts?: Readonly<Record<string, string>>;
  /** How many days a terminal, clean tree stays before a prune may take it. */
  retentionDays: number;
  /**
   * Where one work's record lives on disk, by id, or null when the store
   * holds nothing for it.
   *
   * Handed in rather than built here because the records' home is the
   * profile's, and the manager must not learn where a profile keeps its
   * state to decide whether a tree is orphaned. The record is returned
   * whole, because the tree's state is read off it, not off its existence.
   */
  record: (workId: string) => { state: string } | null;
  /** The states the mounted workflow calls terminal, as it names them. */
  terminalStates: readonly string[];
  /** The log the removals are written to, when there is one. */
  log?: EventLog;
}

interface TreeMeta {
  workId: string;
  repo: string;
  acquiredAt: string;
  updatedAt: string;
}

/**
 * One tree per item, under one root.
 *
 * Layout: `<root>/<workflow>/<workId>/<repo>` — predictable from the things
 * an operator already knows, outside every repository, and removable as a
 * unit. Nothing here resets, repoints or touches a standing checkout:
 * acquisition either creates a tree cut from the default branch or reuses
 * the one that is already there, dirty or not.
 */
export class WorktreeManager implements Worktree {
  constructor(
    private readonly runner: CommandRunner,
    private readonly config: WorktreeManagerConfig,
  ) {}

  async acquire(workId: string, repo: string): Promise<string> {
    const tree = this.pathFor(workId, repo);
    if (fs.existsSync(path.join(tree, ".git"))) {
      this.touch(workId, repo);
      return tree;
    }

    fs.mkdirSync(tree, { recursive: true });

    // Detached at the base branch. A ticket's branch is prepared later;
    // detaching prevents two new trees claiming one branch. The base is the
    // same answer `Git` cuts from, resolved per repository rather than as one
    // name for the whole install.
    const cut = await this.runner.run(
      "git",
      ["worktree", "add", "--detach", tree, this.cutRef(repo)],
      { cwd: this.sourceFor(repo) },
    );

    if (!cut.ok) {
      const message = cut.stderr || cut.stdout;
      throw new Error(`could not create a worktree for ${workId} in ${repo}: ${message}`);
    }

    // A worktree cut straight from a bare repository inherits no remotes.
    // The core Git bridge fetches and pushes through `origin`, so name the
    // source as origin only when the new tree did not inherit one from a
    // standing checkout.
    const remote = await this.runner.run("git", ["remote", "get-url", "origin"], { cwd: tree });
    if (!remote.ok) {
      const added = await this.runner.run("git", ["remote", "add", "origin", repo], { cwd: tree });
      if (!added.ok) {
        throw new Error(`could not name ${repo} as origin for ${tree}: ${added.stderr || added.stdout}`);
      }
    }

    this.writeMeta(workId, repo);
    return tree;
  }

  /** The base branch, named the way the thing being cut from holds it. */
  private cutRef(repo: string): string {
    const { defaultBranch, baseBranch } = this.config;
    return `refs/heads/${baseBranchFor({ workspaceRoot: "", defaultBranch, baseBranch }, repo)}`;
  }

  pathFor(workId: string, repo: string): string {
    return path.join(this.config.root, this.config.workflow, this.safe(workId), this.safe(repo));
  }

  async states(): Promise<WorktreeInfo[]> {
    const base = path.join(this.config.root, this.config.workflow);
    if (!fs.existsSync(base)) return [];

    const now = new Date();
    const found: WorktreeInfo[] = [];

    for (const workId of fs.readdirSync(base)) {
      const workDir = path.join(base, workId);
      if (!fs.statSync(workDir).isDirectory()) continue;

      for (const repo of fs.readdirSync(workDir)) {
        const tree = path.join(workDir, repo);
        if (!fs.existsSync(path.join(tree, ".git"))) continue;

        const meta = this.readMeta(workId, repo);
        found.push(await this.describe(meta?.workId ?? workId, meta?.repo ?? repo, tree, meta, now));
      }
    }

    return found.sort((a, b) => a.workId.localeCompare(b.workId) || a.repo.localeCompare(b.repo));
  }

  async release(workId: string, repo: string, options?: { force?: boolean }): Promise<boolean> {
    const tree = this.pathFor(workId, repo);
    if (!fs.existsSync(path.join(tree, ".git"))) return false;

    const info = await this.describe(workId, repo, tree, this.readMeta(workId, repo), new Date());

    if (!options?.force) {
      const why = refusalFor(info);
      if (why) {
        this.log("worktree.retained", { workId, repo, reason: why });
        throw new Error(`refusing to remove ${tree}: ${why} (use --force to remove it anyway)`);
      }
    }

    await this.remove(tree);
    this.log("worktree.removed", {
      workId,
      repo,
      reason: options?.force ? "removed by hand, over a refusal" : "removed by command",
    });
    return true;
  }

  async prune(_now: Date): Promise<string[]> {
    const removed: string[] = [];

    for (const info of await this.states()) {
      if (!info.prunable) continue;

      await this.remove(info.path);
      this.log("worktree.removed", {
        workId: info.workId,
        repo: info.repo,
        reason: `terminal and clean, past ${this.config.retentionDays} day(s) of retention`,
      });
      removed.push(info.workId);
    }

    // A work directory whose trees are all gone names nothing, which is the
    // same litter as a tree naming nothing.
    this.dropEmptyWorkDirectories();
    return removed;
  }

  /**
   * What one tree is, read off the disk rather than off a memory of what
   * happened.
   *
   * Every field the list names is derived here, in one place, so the CLI and
   * the prune cannot disagree about what `prunable` means.
   */
  private async describe(
    workId: string,
    repo: string,
    tree: string,
    meta: TreeMeta | null,
    now: Date,
  ): Promise<WorktreeInfo> {
    const status = await this.runner.run("git", ["status", "--porcelain"], { cwd: tree });
    const branch = await this.runner.run("git", ["branch", "--show-current"], { cwd: tree });
    const clean = status.ok && status.stdout.length === 0;

    const updatedAt = meta?.updatedAt ?? meta?.acquiredAt ?? now.toISOString();
    const ageDays = (now.getTime() - new Date(updatedAt).getTime()) / 86_400_000;
    const past = ageDays >= this.config.retentionDays;
    const terminal = this.isTerminal(workId);

    return {
      workId,
      repo,
      workflow: this.config.workflow,
      path: tree,
      state: terminal ? "terminal" : this.config.record(workId) ? "in-flight" : "orphaned",
      clean,
      branch: branch.stdout.trim(),
      acquiredAt: meta?.acquiredAt ?? updatedAt,
      updatedAt,
      retentionEligible: past,
      prunable: terminal && clean && past,
    };
  }

  /**
   * Whether the work reached a state the workflow calls terminal.
   *
   * Read off the record, not off the tree: a tree's files cannot say what
   * state its work is in, and the record is the one thing that can.
   */
  private isTerminal(workId: string): boolean {
    const record = this.config.record(workId);
    return record !== null && this.config.terminalStates.includes(record.state);
  }

  private log(event: Parameters<EventLog["append"]>[0]["kind"], detail: Record<string, unknown>): void {
    this.config.log?.append({
      at: new Date().toISOString(),
      kind: event,
      detail,
    });
  }

  private async remove(tree: string): Promise<void> {
    // `git worktree remove` wants to run from inside the repository the tree
    // was cut from, so the gitdir inside the tree names it. Reading it there
    // rather than keeping a second copy of the mapping is what keeps this
    // honest when a tree outlives the config that made it.
    const gitDir = fs.readFileSync(path.join(tree, ".git"), "utf-8").trim();
    const origin = path.resolve(tree, gitDir.replace(/^gitdir:\s*/, "").replace(/\/\.git$/, ""));
    await this.runner.run("git", ["worktree", "remove", "--force", tree], { cwd: origin });
    fs.rmSync(tree, { recursive: true, force: true });
  }

  private refusalFor = refusalFor;

  /**
   * Metadata belongs beside the tree, never inside it: git correctly calls
   * every untracked file in a checkout dirty, and an implementation detail
   * must not make a clean terminal tree impossible to prune.
   */
  private metaFileFor(workId: string, repo: string): string {
    return path.join(
      this.config.root,
      this.config.workflow,
      ".meta",
      this.safe(workId),
      `${this.safe(repo)}.json`,
    );
  }

  private writeMeta(workId: string, repo: string): void {
    const now = new Date().toISOString();
    const meta: TreeMeta = { workId, repo, acquiredAt: now, updatedAt: now };
    const file = this.metaFileFor(workId, repo);
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, `${JSON.stringify(meta, null, 2)}\n`, "utf-8");
  }

  private readMeta(workId: string, repo: string): TreeMeta | null {
    try {
      return JSON.parse(fs.readFileSync(this.metaFileFor(workId, repo), "utf-8")) as TreeMeta;
    } catch {
      return null;
    }
  }

  private touch(workId: string, repo: string): void {
    const meta = this.readMeta(workId, repo);
    if (!meta) return;
    fs.writeFileSync(
      this.metaFileFor(workId, repo),
      `${JSON.stringify({ ...meta, updatedAt: new Date().toISOString() }, null, 2)}\n`,
      "utf-8",
    );
  }

  private dropEmptyWorkDirectories(): void {
    const base = path.join(this.config.root, this.config.workflow);
    if (!fs.existsSync(base)) return;

    for (const entry of fs.readdirSync(base)) {
      if (entry === ".meta") continue;
      const workDir = path.join(base, entry);
      try {
        if (fs.readdirSync(workDir).length === 0) fs.rmdirSync(workDir);
      } catch {
        // A directory that will not let itself be measured keeps standing.
      }
    }
  }

  /** A path segment, made safe to be one. */
  private safe(part: string): string {
    return part.replace(/[^A-Za-z0-9._-]+/g, "-").replace(/^-+|-+$/g, "") || "item";
  }

  /** A logical `owner/repo` lives under the configured standing checkout root. */
  private sourceFor(repo: string): string {
    if (path.isAbsolute(repo)) return repo;
    const named = this.config.checkouts?.[repo];
    if (named !== undefined) return named;
    if (!this.config.workspaceRoot) return repo;
    const name = repo.includes("/") ? repo.slice(repo.indexOf("/") + 1) : repo;
    return path.join(this.config.workspaceRoot, name);
  }
}

/**
 * Why a tree holds its ground, when it does.
 *
 * An in-flight tree is work that is still going; a dirty tree is whatever the
 * agent left behind when a run stopped. Neither is the machine's to delete —
 * the escape hatch is a named command with `--force`, never a predicate.
 */
function refusalFor(info: WorktreeInfo): string | undefined {
  if (info.state === "in-flight") return "the work is still going — retire it first";
  if (!info.clean) return "the tree is dirty, and what is in it is somebody's work";
  return undefined;
}

import os from "node:os";
import path from "node:path";
import fs from "node:fs";
import { WORKSPACE_PORT, ConfigOf, OperationContext, PluginContext, Worktree, Workspace, baseBranchesOf, defineOperation, definePlugin, fail } from "@amykit/core";
import { z } from "zod";
import { configSchema } from "./config.js";

type TypedContext = PluginContext<ConfigOf<typeof configSchema>>;
import { WorktreeManager, WorktreeManagerConfig } from "./manager.js";

/** `~/worktrees` becomes an absolute path. */
function expandHome(value: string): string {
  if (value === "~") return os.homedir();
  if (value.startsWith("~/")) return path.join(os.homedir(), value.slice(2));
  return value;
}

/**
 * Builds the manager's settings, naming what was not configured.
 *
 * `workflow` has no default this plugin could invent: the tree paths carry
 * the workflow's name so two profiles under one install never share a tree,
 * and a mount that cannot say which it is is refused rather than guessed.
 */
function settingsFor(ctx: TypedContext): WorktreeManagerConfig {
  // The CLI always derives this from the selected profile. The neutral docs
  // mount has no selected workflow, so it receives a harmless label solely to
  // enumerate the port rather than refusing documentation generation.
  const workflow = (ctx.config.workflow) || "unconfigured";

  const root = (ctx.config.root) || path.join(ctx.paths.state, "worktrees");
  const recordsDirectory = (ctx.config.recordsDirectory) || path.join(ctx.paths.state, "records");

  const workspace = workspaceFor(ctx);
  return {
    root: expandHome(root),
    workflow,
    defaultBranch: ctx.config.defaultBranch,
    baseBranch: baseBranchesOf(ctx.config),
    workspaceRoot: workspace.workspaceRoot,
    checkouts: workspace.checkouts,
    retentionDays: ctx.config.retentionDays,
    // Read on every look, never folded in at mount: a record deleted under a
    // running install turns its tree orphaned at the next list, which is the
    // truth about what the store holds now.
    record: (workId) => {
      try {
        return JSON.parse(fs.readFileSync(path.join(recordsDirectory, `${rootRecordId(workId)}.json`), "utf-8")) as {
          state: string;
        };
      } catch {
        return null;
      }
    },
    terminalStates: ctx.workflow()?.terminalStates ?? [],
    log: ctx.log,
  };
}

/** Called pieces live inside their root record, while a worktree remains root-owned. */
function rootRecordId(workId: string): string {
  return workId.split("/", 1)[0] ?? workId;
}

/**
 * The workplace this slice carries, expanded the way the machine expanded it.
 *
 * The workspace is the plugin's own vocabulary now, so its paths are read off
 * the slice and made absolute here — the one expansion, in the one place that
 * mounts the port every `checkouts()` answer goes through.
 */
function workspaceFor(ctx: TypedContext): Workspace {
  const checkouts = ctx.config.checkouts ?? {};
  return {
    workspaceRoot: expandHome(ctx.config.workspaceRoot),
    checkouts: Object.fromEntries(
      Object.entries(checkouts as Record<string, unknown>).map(([repo, value]) => [repo, expandHome(String(value))]),
    ),
  };
}

/** The port this plugin mounted; the operations below all declare `mount: true`. */
function managed(context: OperationContext): Worktree {
  return context.port("worktree") as Worktree;
}

const tree = z.object({
  workId: z.string().describe("work"),
  workflow: z.string().describe("workflow"),
  repo: z.string().describe("repo"),
  branch: z.string().describe("branch"),
  state: z.enum(["in-flight", "terminal", "orphaned"]).describe("state"),
  tree: z.enum(["clean", "dirty"]).describe("tree"),
  retention: z.enum(["held", "past retention"]).describe("retention"),
  path: z.string().describe("path"),
});

/**
 * The trees, as this plugin's own operations: `amy worktrees`, `amy
 * worktrees remove` and `amy worktrees prune`.
 *
 * `mount: true`, because what a tree is worth removing depends on the
 * workflow's terminal states — a fact only the mounted manager holds. On a
 * machine that will not assemble each is refused by name rather than
 * answering with every tree reading as in flight.
 */
const listTrees = defineOperation({
  id: "worktree.list-trees",
  domain: "worktree",
  summary: "Name every worktree: state, workflow, work id, repo, branch, cleanliness, retention",
  description:
    "Lists every tree the mounted manager holds, with the state of the work it belongs to. An orphaned tree names work the store no longer holds; " +
    "`amy worktrees remove <workId> --force` recovers it. Changes nothing.",
  input: z.object({}),
  output: z.array(tree).describe("worktrees"),
  writes: [],
  mount: true,
  http: { method: "get", path: "/worktrees" },
  cli: { words: ["worktrees", "list"], default: true },
  examples: [{
    summary: "one finished, clean tree",
    input: {},
    output: [{
      workId: "tickets/ACME-1",
      workflow: "tickets",
      repo: "acme/api",
      branch: "acme-1-fix",
      state: "terminal",
      tree: "clean",
      retention: "past retention",
      path: "/home/amy/worktrees/tickets/ACME-1/api",
    }],
  }],
  async handler(_input, context) {
    const states = await managed(context).states();
    return states.map((state) => ({
      workId: state.workId,
      workflow: state.workflow,
      repo: state.repo,
      branch: state.branch || "(detached)",
      state: state.state,
      tree: state.clean ? "clean" as const : "dirty" as const,
      retention: state.retentionEligible ? "past retention" as const : "held" as const,
      path: state.path,
    }));
  },
});

const removeTree = defineOperation({
  id: "worktree.remove-tree",
  domain: "worktree",
  summary: "Remove one worktree, refusing an in-flight or dirty one unless --force",
  description: "Removes every tree the named work holds. An in-flight or dirty tree is refused unless `force` says otherwise; nothing else is touched.",
  input: z.object({
    workId: z.string().describe("the work whose tree is to go"),
    force: z.boolean().default(false).describe("remove it even though the refusal applies"),
  }),
  output: z.object({ removed: z.number().int().describe("removed") }),
  errors: {
    "worktree.not_found": { description: "no tree belongs to the work named" },
    "worktree.refused": { description: "the tree is in flight or dirty, and force was not given" },
  },
  writes: ["worktree"],
  mount: true,
  http: { method: "delete", path: "/worktrees/{workId}" },
  cli: { words: ["worktrees", "remove"], positional: ["workId"] },
  examples: [{ summary: "a finished tree", input: { workId: "tickets/ACME-1" }, output: { removed: 1 } }],
  async handler({ workId, force }, context) {
    const manager = managed(context);
    const found = (await manager.states()).filter((state) => state.workId === workId);
    if (found.length === 0) return fail("worktree.not_found", `no worktree for ${workId}`);

    // The safety refusal is read from the trees' own states, so it is the one
    // failure answered as declared; anything `release` throws past it — a
    // broken checkout, a git that failed — is not a refusal, and propagates.
    const refusals = force ? [] : found.filter((state) => state.state === "in-flight" || !state.clean);
    if (refusals.length > 0) {
      const why = refusals.map((state) => `${state.path} is ${state.state === "in-flight" ? "still in flight" : "dirty"}`).join("; ");
      return fail("worktree.refused", `refusing to remove the tree(s) for ${workId}: ${why} (use --force to remove them anyway)`);
    }

    let removed = 0;
    for (const state of found) {
      if (await manager.release(workId, state.repo, { force })) removed += 1;
    }
    return { removed };
  },
});

const pruneTrees = defineOperation({
  id: "worktree.prune-trees",
  domain: "worktree",
  summary: "Remove every terminal, clean tree past its retention, and nothing else",
  description: "Removes the trees an automatic prune may remove: terminal, clean and past retention. A dirty, in-flight or orphaned tree is left where it is.",
  input: z.object({}),
  output: z.object({ removed: z.array(z.string()).describe("removed") }),
  writes: ["worktree"],
  mount: true,
  http: { method: "post", path: "/worktrees/prune" },
  cli: { words: ["worktrees", "prune"] },
  examples: [{ summary: "nothing past retention", input: {}, output: { removed: [] } }],
  async handler(_input, context) {
    return { removed: await managed(context).prune(new Date()) };
  },
});

/**
 * The workplace, mounted.
 *
 * The port is mounted unconditionally when this plugin is listed — a port
 * with nothing behind it is a boot refusal, and a directory costs nothing —
 * while the workflows that consume it read it as `Worktree | undefined` and
 * run unchanged when no install listed this plugin.
 */
export const plugin = definePlugin<typeof configSchema>({
  name: "@amykit/plugin-file-worktree",
  configSchema,
  operations: [listTrees, removeTree, pruneTrees],
  register(registry, ctx) {
    registry.port(WORKSPACE_PORT, workspaceFor(ctx));
    registry.port("worktree", new WorktreeManager(ctx.runner, settingsFor(ctx)));
  },
});
